const preferredTime = String(body.preferredTime ?? '');

const now = new Date();
const timeZone = 'Europe/Budapest';

function partsInBudapest(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    weekday: 'short',
  }).formatToParts(date);
  return Object.fromEntries(parts.map((p) => [p.type, p.value]));
}

function makeBudapestDate(year,month,day,hour,minute) { return localDate(year,month,day,hour,minute); }

function spokenFor(date) {
  const parts = new Intl.DateTimeFormat('hu-HU', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(date);
  const byType = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return byType.year + '.' + byType.month + '.' + byType.day + '. ' + byType.hour + ':' + byType.minute;
}

// --- Preferred-time parsing (Hungarian, best-effort) ---
// A hívó preferenciáját NEM a modell számolja ki, hanem itt, a backendben,
// egyszerű kulcsszó-illesztéssel — így a checkAvailability a legközelebbi
// releváns napokat tudja előnyben részesíteni, nem csak a naptárilag legkorábbit.
function parsePreferredHint(text) {
  if (!text) return { weekOffset: 0, targetWeekday: null, dayOffset: null, timeOfDay: null };
  const lower = text.toLowerCase();

  const weekdayMap = {
    'hétfő': 1, 'hétfőn': 1,
    'kedd': 2, 'kedden': 2,
    'szerda': 3, 'szerdán': 3,
    'csütörtök': 4, 'csütörtökön': 4,
    'péntek': 5, 'pénteken': 5,
    'szombat': 6, 'szombaton': 6,
    'vasárnap': 0,
  };

  let weekOffset = 0;
  if (/két\s*hét|2\s*hét/.test(lower)) weekOffset = 2;
  else if (/jövő\s*hét|következő\s*hét|jövőhét/.test(lower)) weekOffset = 1;

  let targetWeekday = null;
  for (const [word, day] of Object.entries(weekdayMap)) {
    if (lower.includes(word)) { targetWeekday = day; break; }
  }

  let dayOffset = null;
  if (/holnapután/.test(lower)) dayOffset = 2;
  else if (/holnap/.test(lower)) dayOffset = 1;
  else if (/\bma\b/.test(lower)) dayOffset = 0;

  const timeOfDay = /délután/.test(lower) ? 'afternoon'
    : /délelőtt|reggel/.test(lower) ? 'morning'
    : null;

  return { weekOffset, targetWeekday, dayOffset, timeOfDay };
}

const hint = parsePreferredHint(preferredTime);

// A hívó szavaiból becsült célnap (csak dátum-eltolás becslés, nem pontos —
// a Filter free slots node ezt csak a rendezéshez/rangsoroláshoz használja,
// sosem szűr ki vele érvényes, szabad időpontot).
let preferredDayOffsetGuess = null;
if (hint.dayOffset !== null) {
  preferredDayOffsetGuess = hint.dayOffset;
} else if (hint.targetWeekday !== null) {
  const today=parts(now); const nowWeekday = new Date(Date.UTC(+today.year,+today.month-1,+today.day)).getUTCDay(); // 0=Sun..6=Sat

  if (hint.weekOffset > 0) {
    // Explicit "jövő hét" / "X hét múlva" + konkrét nap: a célhét (naptári, hétfőtől
    // induló) adott napjára számolunk — NEM a legközelebbi előfordulás + plusz hét,
    // mert ha a legközelebbi előfordulás már úgyis a következő naptári hétre esik
    // (pl. csütörtökön hívnak és keddet mondanak), a régi képlet duplán számolta a hetet.
    const daysSinceMonday = (nowWeekday + 6) % 7; // Mon=0..Sun=6
    const targetWeekMondayOffset = -daysSinceMonday + hint.weekOffset * 7;
    const targetWeekdayFromMonday = (hint.targetWeekday + 6) % 7; // Mon=0..Sun=6
    preferredDayOffsetGuess = targetWeekMondayOffset + targetWeekdayFromMonday;
  } else {
    // Nincs explicit hét-eltolás — a legközelebbi jövőbeli előfordulást értjük.
    let diff = (hint.targetWeekday - nowWeekday + 7) % 7;
    if (diff === 0) diff = 7; // "kedd" hallatán mindig a következő keddet értjük, nem a mait
    preferredDayOffsetGuess = diff;
  }
