// Korábban a ciklus 12 jelöltnél (= 1 nap összes időpontja) leállt, így a preferredTime
// gyakorlatilag sosem tudott hatni. Most a keresés a teljes 60 napos ablakot végigjárja,
// és minden hétköznapról összegyűjti a jövőbeli időpontokat.
const starts = [];
const MAX_CANDIDATES = 61 * 7; // A teljes 60 napos keresési ablak minden félórás jelöltje.
for (let add = 0; add <= 60 && starts.length < MAX_CANDIDATES; add++) {
  const todayParts=partsInBudapest(now); const d = new Date(+localDate(+todayParts.year,+todayParts.month,+todayParts.day+add,12,0));
  const parts = partsInBudapest(d);
  const year = Number(parts.year);
  const month = Number(parts.month);
  const day = Number(parts.day);
  const weekday = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
  if (![1, 2, 3, 4, 5].includes(weekday)) continue;

  const candidateTimes = [[9,30],[10,30],[11,30],[12,30],[13,30],[14,30],[15,30]];

  for (const [hour, minute] of candidateTimes) {
    const start = makeBudapestDate(year, month, day, hour, minute);
    if (policyError(+start,+start+30*60000,+now)) continue;
    const end = new Date(start.getTime() + 30 * 60 * 1000);
    starts.push({ start, end, dayOffset: add });
    if (starts.length >= MAX_CANDIDATES) break;
  }
}

return [{
  json: {
    excludedStarts: String(body.excludedStarts || "").split(",").map(s=>s.trim()).filter(Boolean),
    preferredTime,
    preferredDayOffsetGuess,
