const built = $('Build consultation candidate slots').first().json;
const candidates = built.candidateSlots ?? [];
const events = $('Get consultation calendar events').all().map((item) => item.json);
const preferredDayOffsetGuess = built.preferredDayOffsetGuess;
const preferredTimeOfDay = built.preferredTimeOfDay;

function eventStart(event) {
  return event.start?.dateTime ?? event.start?.date ?? event.start;
}
function eventEnd(event) {
  return event.end?.dateTime ?? event.end?.date ?? event.end;
}
function overlaps(aStart, aEnd, bStart, bEnd) {
  return new Date(aStart) < new Date(bEnd) && new Date(aEnd) > new Date(bStart);
}

let free;
try {
  const all=events;
  const excluded=new Set((built.excludedStarts||[]).map(Date.parse));
  free=candidates.filter(slot=>!excluded.has(Date.parse(slot.start))&&policyAvailable(all,Date.parse(slot.start),Date.parse(slot.end)));
} catch(e) {return [{json:{success:false,http_status:503,slots:[],message:'A naptár nem ellenőrizhető. Ne ajánljon időpontot; próbálja újra később.'}}];}

// Rangsorolás a hívó preferenciájához (nap, majd délelőtt/délután) —
// csak a SORRENDET módosítja a kronologikus alapértelmezetthez képest,
// szabad időpontot sosem zár ki. Ha nincs értelmezhető preferencia,
// az eredeti, kronologikus sorrend marad (legkorábbi elöl).
function timeOfDayMatches(slot) {
  if (!preferredTimeOfDay) return true;
  const hour = Number(parts(slot.start).hour);
  return preferredTimeOfDay === 'afternoon' ? hour >= 12 : hour < 12;
}

let ranked = free;
if (preferredDayOffsetGuess !== null && preferredDayOffsetGuess !== undefined) {
  ranked = [...free].sort((a, b) => {
    const distA = Math.abs(a.dayOffset - preferredDayOffsetGuess);
    const distB = Math.abs(b.dayOffset - preferredDayOffsetGuess);
    if (distA !== distB) return distA - distB;
    const timeMatchA = timeOfDayMatches(a) ? 0 : 1;
    const timeMatchB = timeOfDayMatches(b) ? 0 : 1;
    if (timeMatchA !== timeMatchB) return timeMatchA - timeMatchB;
    return new Date(a.start) - new Date(b.start);
  });
} else if (preferredTimeOfDay) {
  ranked = [...free].sort((a, b) => {
    const timeMatchA = timeOfDayMatches(a) ? 0 : 1;
    const timeMatchB = timeOfDayMatches(b) ? 0 : 1;
    if (timeMatchA !== timeMatchB) return timeMatchA - timeMatchB;
    return new Date(a.start) - new Date(b.start);
  });
}

const first=ranked[0];
const second=first && (preferredDayOffsetGuess==null ? ranked.find(s=>s.dayOffset!==first.dayOffset) || ranked[1] : ranked[1]);
const top2=[first,second].filter(Boolean).map(({start,end,spoken})=>({start,end,spoken}));

return [{
  json: {
    success: top2.length > 0,
    slots: top2,
    message: top2.length > 0
      ? 'Szabad időpontok lekérdezve.'
      : 'A következő 60 napban nincs megfelelő szabad időpont. Kérjen más időpontpreferenciát; ne ígérjen foglalást vagy booking linket.',
  },
}];

