let secret;try{secret=$env.LEAD_CALL_WEBHOOK_SECRET;}catch(e){}
if(!secret)return [{json:{verified:false,http_status:503,reason:'webhook_secret_not_configured'}}];
const crypto=require('crypto');
const input=$input.first(),sig=String(input.json.headers?.['elevenlabs-signature']||'');
const fields=sig.split(',').map(s=>s.trim().split('=')),ts=fields.find(x=>x[0]==='t')?.[1],signatures=fields.filter(x=>x[0]==='v0').map(x=>x[1]);
if(!/^\d+$/.test(ts||'')||Math.abs(Date.now()/1000-Number(ts))>300)return [{json:{verified:false,http_status:401,reason:'invalid_timestamp'}}];
let raw;try{raw=await this.helpers.getBinaryDataBuffer(0,'data');}catch(e){return [{json:{verified:false,http_status:400,reason:'raw_body_required'}}];}
const expected=crypto.createHmac('sha256',secret).update(ts+'.').update(raw).digest();
const valid=signatures.some(s=>/^[a-f0-9]{64}$/i.test(s||'')&&crypto.timingSafeEqual(expected,Buffer.from(s,'hex')));
if(!valid)return [{json:{verified:false,http_status:401,reason:'invalid_signature'}}];
let e;try{e=JSON.parse(raw.toString('utf8'));}catch(err){return [{json:{verified:false,http_status:400,reason:'invalid_json'}}];}
const d=e.data||{};
const failureReason=String(d.failure_reason||d.error?.reason||d.metadata?.error?.reason||e.failure_reason||'').toLowerCase().trim();
const normalizedFailure=failureReason.replace(/[_-]+/g,' ').replace(/\s+/g,' ');
const retryableFailure=/(^|\b)(no answer|busy|timeout|timed out|sip request timed out|temporarily unavailable|service unavailable|gateway timeout|network error)(\b|$)/i.test(normalizedFailure);
const conversationId=String(d.conversation_id||d.metadata?.conversation_id||e.conversation_id||'');
const agentId=String(d.agent_id||d.metadata?.agent_id||e.agent_id||'');
const retry_candidate=e.type==='call_initiation_failure'&&agentId==='agent_7601m2wnkpmff0ta6bqg5adnmmax'&&retryableFailure&&/^conv_[a-zA-Z0-9]+$/.test(conversationId);
return [{json:{verified:true,http_status:200,retry_candidate,conversation_id:conversationId,failure_reason:failureReason,event_timestamp:e.event_timestamp}}];

const ZONE = 'Europe/Budapest';
function parts(date) { return Object.fromEntries(new Intl.DateTimeFormat('en-CA', {timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(date)).map(p=>[p.type,p.value])); }
function localDate(y,m,d,h=0,min=0) {
  const target=Date.UTC(y,m-1,d,h,min); let guess=target;
  for(let i=0;i<4;i++) {const p=parts(guess); const wall=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second);const diff=target-wall;if(!diff)return new Date(guess);guess+=diff;}
  throw Error('Nem egyértelmű helyi időpont.');
}

function callTime(value) {
 let t=Math.max(Number(value),Date.now());
 for(let i=0;i<8;i++) {const p=parts(t),dow=new Date(Date.UTC(+p.year,+p.month-1,+p.day)).getUTCDay(),m=+p.hour*60 + +p.minute;
  if(dow>=1&&dow<=5&&m>=480&&m<1200)return t;
  if(dow>=1&&dow<=5&&m<480)return +localDate(+p.year,+p.month,+p.day,8);
  t=+localDate(+p.year,+p.month,+p.day+1,8);
 } throw Error('Cannot schedule call');
}

const e=$('Verify call result signature').first().json,c=$json,v=c.conversation_initiation_client_data?.dynamic_variables||{};
if(c.agent_id!=='agent_7601m2wnkpmff0ta6bqg5adnmmax'||c.conversation_id!==e.conversation_id)throw Error('Conversation mismatch');
if(c.status!=='failed'||(c.transcript||[]).some(t=>t.role==='user')||c.metadata?.call_duration_secs>0)return [];
const previous=Number(v.followup_attempt),first=Date.parse(v.followup_first_at),last=Date.parse(v.followup_last_at);
if(!Number.isInteger(previous)||previous<1||previous>3||!Number.isFinite(first)||!Number.isFinite(last)||last<first||last>Date.now()+60000)throw Error('Missing or invalid retry state; inspect manually');
if(previous>=3)return [];
if(!v.lead_id||!/^\+[1-9]\d{7,14}$/.test(v.lead_phone||''))throw Error('Missing retry lead identity');
const at=callTime(Math.max(first+(previous===1?15:120)*60000,last+15*60000,Date.now()));
return [{json:{lead_id:String(v.lead_id),lead_name:String(v.lead_name||'Érdeklődő'),email:String(v.lead_email||''),phone:v.lead_phone,company_name:String(v.company_name||''),interested_solution:String(v.interested_solution||''),monthly_budget:String(v.monthly_budget||''),desired_timing:String(v.desired_timing||''),attempt_number:previous+1,first_attempt_at:v.followup_first_at,next_call_at:new Date(at).toISOString(),source:'verified_no_answer'}}];

