parameters.jsCode:
let secret;try{secret=$env.WEBSITE_LEAD_WEBHOOK_SECRET;}catch(e){}
const crypto=require('crypto');
const fail=(status,reason)=>[{json:{accepted:false,success:false,http_status:status,reason}}];
if(!secret)return fail(503,'webhook_secret_not_configured');
const item=$input.first().json,h=item.headers||{},b=item.body;
const hash=v=>crypto.createHash('sha256').update(String(v)).digest();
if(!crypto.timingSafeEqual(hash(h['x-lead-secret']||''),hash(secret)))return fail(401,'unauthorized');
if(!b||typeof b!=='object'||Array.isArray(b))return fail(400,'invalid_body');
// honeypot: robotok kitöltik, emberek nem látják; csendben eldobjuk
if(String(b.website_url||b.hp||'').trim())return [{json:{accepted:false,success:true,http_status:200,reason:'ignored'}}];
const clean=(v,max=300)=>String(v==null?'':v).replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
const consent=/^(true|1|on|yes|igen)$/i.test(String(b.consent));
if(!consent)return fail(422,'consent_required');
let phone=clean(b.phone_number||b.phone,40).replace(/[\s().-]/g,'').replace(/^p:/,'');
if(phone.startsWith('00'))phone='+'+phone.slice(2);
else if(phone.startsWith('06'))phone='+36'+phone.slice(2);
else if(/^36\d{8,9}$/.test(phone))phone='+'+phone;
else if(/^\d{8,9}$/.test(phone))phone='+36'+phone;
if(!/^\+[1-9]\d{7,14}$/.test(phone)||(/^\+36/.test(phone)&&!/^\+36\d{8,9}$/.test(phone)))return fail(422,'invalid_phone');
const email=clean(b.email,200).toLowerCase();
if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return fail(422,'invalid_email');
const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Budapest'}).format(new Date());
// azonos telefonszám ugyanazon a napon ugyanazt a lead ID-t kapja (duplikáció-védelem)
const id='w:'+crypto.createHash('sha256').update(phone+'|'+day).digest('hex').slice(0,20);
return [{json:{
  accepted:true,id,created_time:new Date().toISOString(),
  full_name:clean(b.full_name||b.name,120),email,phone_number:phone,company_name:clean(b.company_name||b.company,160),
  'mi_a_legnagyobb_problémáid_jelenleg_a_telefonhívások_kezelésével?':clean(b.message||b.call_handling_problem,1000),
  'melyik_területen_működik_a_vállalkozásod?':clean(b.industry,200),
  'mekkora_havi_keretet_tudnál_erre_fordítani?':clean(b.monthly_budget,100),
  'hogyan_írnád_le_a_szereped_a_döntésben?':clean(b.decision_role,100),
  'mikor_szeretnél_megoldást_találni?':clean(b.desired_timing,100),
  form_id:'website',__source:'website_form',page_url:clean(b.page_url,500)
}}];

const lead=$('Prepare website lead').first().json,rows=$input.all().map(x=>x.json);
if(rows.some(x=>x.error))return [{json:{...lead,sheet_ok:false,duplicate:false,success:false,http_status:503,reason:'sheet_unavailable'}}];
const duplicate=rows.some(r=>String(r.id||'').trim()===lead.id);
return [{json:{...lead,sheet_ok:true,duplicate,success:true,http_status:200,reason:duplicate?'duplicate':'accepted'}}];
